// Launch Params: the launch row is the whole contract of Discover Storeleads Companies (brought to
// the Rootflows standard 2026-09-10): Client (resolves the base), Tag (optional, stamped on every
// company landed), and the Storeleads source variables, which for this Rootflow ARE the source: an
// Insert runs on a source, and Storeleads has no saved query, so the filter set is it. Max companies
// is the spend cap the loop enforces, and Storeleads is metered, so it is required.
//
// The source variables, exactly the Hub columns Build SL Query reads: Country, Platforms, Plan,
// Monthly revenue, Employees, Product count, Store age, Min monthly visits, Category, Technologies,
// Must-have app IDs, Max companies. Table is implied (Companies). Nothing else is read: the contacts
// pull this Rootflow fires afterwards is Enrich Contacts with its own rules, so the old contacts
// parameters (Tiers, Sources, Departments, Roles) are dead and dropped.
//
// REFUSALS. A badly filled launch row is an expected outcome, not a crash, and it must be visible on
// the row the Operator launched: every guard RETURNS a refusal item (`refused` carries the reason),
// Launch OK? routes it to Build Refusal, which closes the row as Failed with the reason and the
// link. Nothing is pulled and nothing is written.
const rec=$('Fetch Launch Record').first().json||{};
const f=rec.fields||{};
const cf=(($('Resolve Base').first().json||{}).fields)||{};
const base=((cf['Clayroots Base ID']||'')+'').trim();
const arr=(v)=>Array.isArray(v)?v:(v==null||v===''?[]:[v]);
const clientRecId=(arr(f['Client']).map(x=>(x&&typeof x==='object')?x.id:x)[0])||'';
const tag=((f['Tag']||'')+'').trim();
const list=(v)=>Array.isArray(v)?v.map(x=>String(x).trim()).filter(Boolean):((v==null||v==='')?[]:String(v).split(',').map(s=>s.trim()).filter(Boolean));
const text=(v)=>(v==null?'':String(v)).trim();
const maxCompanies=parseInt(f['Max companies'],10);
const visits=f['Min monthly visits'];
const src={
  country: list(f['Country']),
  platforms: list(f['Platforms']),
  plan: list(f['Plan']),
  monthlyRevenue: list(f['Monthly revenue']),
  employees: list(f['Employees']),
  productCount: list(f['Product count']),
  storeAge: list(f['Store age']),
  minMonthlyVisits: (visits==null||visits==='')?null:Number(visits),
  category: text(f['Category']),
  technologies: text(f['Technologies']),
  mustHaveAppIds: text(f['Must-have app IDs'])
};
const anyFilter=src.country.length||src.platforms.length||src.plan.length||src.monthlyRevenue.length||src.employees.length||src.productCount.length||src.storeAge.length||(Number.isFinite(src.minMonthlyVisits)&&src.minMonthlyVisits>0)||src.category||src.technologies||src.mustHaveAppIds;
const startedAt=new Date().toISOString();
const where='Launch record '+(rec.id||'?');
const shape=Object.assign({ refused:'', base, clientRecId, tag, maxCompanies: Number.isFinite(maxCompanies)?maxCompanies:null, _launchRecordId: rec.id||'', startedAt }, src);
const refuse=(reason)=>[{ json: Object.assign({}, shape, { refused: reason }) }];
if(!clientRecId){ return refuse(where+' has no Client link. Nothing was pulled.'); }
if(!/^app[A-Za-z0-9]{14}$/.test(base)){ return refuse('Client on '+where.toLowerCase()+' has no valid Clayroots Base ID. Nothing was pulled.'); }
if(!Number.isFinite(maxCompanies)||maxCompanies<1){ return refuse(where+' has no Max companies. Storeleads is metered and it is the spend cap of this run. Nothing was pulled.'); }
if(!anyFilter){ return refuse(where+' carries no Storeleads filter. The filter set is this Rootflow\'s source: tick at least one of Country, Platforms, Plan, Monthly revenue, Employees, Product count, Store age, Min monthly visits, Category, Technologies, Must-have app IDs. Nothing was pulled.'); }
return [{ json: shape }];

// Build Refusal: the row a badly filled launch writes. Launch Params names the reason instead of
// throwing, Launch OK? routes here, and this closes the launch row (already stamped Running with
// this Execution ID) as Failed with the reason and the link. Nothing ran, and no metered Storeleads
// page was ever asked for.
const p=$('Launch Params').first().json||{};
const reason=String(p.refused||'the launch row was refused and no reason was recorded');
const show=(v)=>(v===''||v===null||v===undefined)?'(empty)':String(v);
const arr=(v)=>Array.isArray(v)&&v.length?v.join(', '):'(empty)';
const lines=[
  '**Refused before anything ran: '+reason+'**',
  '',
  '**The launch row as this Rootflow read it**',
  '- **Client:** '+show(p.clientRecId),
  '- **Clayroots Base ID:** '+(p.base||'(empty, or the Clients row could not be read)'),
  '- **Max companies:** '+show(p.maxCompanies),
  '- **Tag:** '+show(p.tag),
  '- **Country:** '+arr(p.country),
  '- **Platforms:** '+arr(p.platforms),
  '- **Plan:** '+arr(p.plan),
  '- **Monthly revenue:** '+arr(p.monthlyRevenue),
  '- **Employees:** '+arr(p.employees),
  '- **Product count:** '+arr(p.productCount),
  '- **Store age:** '+arr(p.storeAge),
  '- **Min monthly visits:** '+show(p.minMonthlyVisits),
  '- **Category:** '+show(p.category),
  '- **Technologies:** '+show(p.technologies),
  '- **Must-have app IDs:** '+show(p.mustHaveAppIds),
  '',
  '**Failures (1)**',
  '- Launch guard: '+reason,
  '',
  'Storeleads was not called and nothing was written to the client base.',
  'Fill the named field on the launch row, clear Execution ID and Status, and the launch automation fires it again.'
];
let dur=0; try{ dur=Math.max(0,Math.round(($now.toMillis()-new Date(p.startedAt).getTime())/1000)); }catch(e){}
const log={ 'Automation':'Discover Storeleads Companies', 'Status':'Failed', 'Trigger':'form', 'Errors':1, 'Run at':$now.toISO(), 'Records In':0, 'Records Out':0, 'Duration s':dur, 'Description':lines.join('\n'), 'Execution Link':'https://n8n.flowroots.com/workflow/'+$workflow.id+'/executions/'+$execution.id, 'Execution ID':String($execution.id) };
if(p.clientRecId) log['Client']=[p.clientRecId];
return [{ json: log }];

// Build SL Query: the launch row's Storeleads filters, which are this Rootflow's source, become one
// pull query per provider x country. Max companies (already validated by Launch Params) is the spend
// cap the loop enforces; each batch pulls only what is still short of it.
const lp = $('Launch Params').first().json;
const CMAP = {'United States':'US','United Kingdom':'GB','Canada':'CA','Australia':'AU','Ireland':'IE','Israel':'IL','Germany':'DE','France':'FR','Netherlands':'NL','usa':'US','us':'US','uk':'GB','england':'GB'};
const asArr=(v)=>{ if(v===undefined||v===null||v==='')return[]; if(Array.isArray(v))return v.map(x=>String(x).trim()).filter(Boolean); return String(v).split(',').map(s=>s.trim()).filter(Boolean); };
const toCode=(x)=>{ const s=String(x).trim(); if(CMAP[s])return CMAP[s]; if(CMAP[s.toLowerCase()])return CMAP[s.toLowerCase()]; if(/^[A-Za-z]{2}$/.test(s))return s.toUpperCase(); return ''; };
const ccList = Array.from(new Set(asArr(lp.country).map(toCode).filter(Boolean)));
const ALLOWED = ['shopify','woocommerce','bigcommerce','wix','squarespace','magento'];
let selP = asArr(lp.platforms).map(s=>String(s).toLowerCase()).filter(s=>ALLOWED.includes(s));
const planTicked = asArr(lp.plan).includes('Shopify Plus');
if (planTicked) selP = ['shopify'];
const providers = selP.length ? Array.from(new Set(selP)) : ['all'];
// Max companies is guaranteed by Launch Params (a missing cap is refused on the launch row, never
// thrown here), so this only reads it; the 1 floor is belt and braces, not a guard.
const maxCompanies = Math.max(1, parseInt(lp.maxCompanies, 10) || 1);
const baseFilters = { 'f:state': 'Active' };
if (planTicked) baseFilters['f:plan'] = 'Shopify Plus';
const envelope=(ticked, ORDER, MAP)=>{ const s=ticked.filter(b=>MAP[b]); if(!s.length) return [null,null]; const idxs=s.map(b=>ORDER.indexOf(b)).filter(i=>i>=0).sort((a,b)=>a-b); return [MAP[ORDER[idxs[0]]][0], MAP[ORDER[idxs[idxs.length-1]]][1]]; };
const REV_ORDER=['Under $10k','$10k-50k','$50k-100k','$100k-500k','$500k-1M','$1M+'];
const REV={'Under $10k':[null,1000000],'$10k-50k':[1000000,5000000],'$50k-100k':[5000000,10000000],'$100k-500k':[10000000,50000000],'$500k-1M':[50000000,100000000],'$1M+':[100000000,null]};
const rev=envelope(asArr(lp.monthlyRevenue),REV_ORDER,REV);
if(rev[0]!=null)baseFilters['f:ermin']=String(rev[0]); if(rev[1]!=null)baseFilters['f:ermax']=String(rev[1]);
const EMP_ORDER=['1-10','11-50','51-200','200+'];
const EMP={'1-10':[1,10],'11-50':[11,50],'51-200':[51,200],'200+':[200,null]};
const emp=envelope(asArr(lp.employees),EMP_ORDER,EMP);
if(emp[0]!=null)baseFilters['f:empcmin']=String(emp[0]); if(emp[1]!=null)baseFilters['f:empcmax']=String(emp[1]);
const PC_ORDER=['1-50','51-500','500+'];
const PC={'1-50':[1,50],'51-500':[51,500],'500+':[500,null]};
const pc=envelope(asArr(lp.productCount),PC_ORDER,PC);
if(pc[0]!=null)baseFilters['f:pcmin']=String(pc[0]); if(pc[1]!=null)baseFilters['f:pcmax']=String(pc[1]);
const iso=(d)=>d.toISOString().slice(0,19)+'Z';
const now=new Date();
const yearsAgo=(y)=>{ const d=new Date(now.getTime()); d.setUTCFullYear(d.getUTCFullYear()-y); return d; };
const AGE_ORDER=['Under 1 year','1-3 years','3+ years'];
const AGE={'Under 1 year':[0,1],'1-3 years':[1,3],'3+ years':[3,null]};
const ageTicked=asArr(lp.storeAge).filter(b=>AGE[b]);
if(ageTicked.length){ const aidx=ageTicked.map(b=>AGE_ORDER.indexOf(b)).filter(i=>i>=0).sort((a,b)=>a-b); const minAge=AGE[AGE_ORDER[aidx[0]]][0]; const maxAge=AGE[AGE_ORDER[aidx[aidx.length-1]]][1]; if(maxAge!=null)baseFilters['f:cratmin']=iso(yearsAgo(maxAge)); if(minAge>0)baseFilters['f:cratmax']=iso(yearsAgo(minAge)); }
const minVisits = parseInt(lp.minMonthlyVisits, 10);
if (Number.isFinite(minVisits) && minVisits > 0) baseFilters['f:evmin'] = String(minVisits);
const catList = asArr(lp.category);
if (catList.length) { baseFilters['f:cat'] = catList.join(','); baseFilters['f:cat:op'] = 'or'; }
const techList = asArr(lp.technologies);
if (techList.length) { baseFilters['f:tech'] = techList.join(','); baseFilters['f:tech:op'] = 'and'; }
const appIds = asArr(lp.mustHaveAppIds);
if (appIds.length) { baseFilters['f:an']=appIds.join(','); baseFilters['f:an:op']='and'; }
const fields = 'name,tld1,merchant_name,title,description,categories,country_code,city,administrative_area_level_1,estimated_sales,employee_count,rank,platform,state,plan,created_at,product_count,monthly_app_spend,apps,technologies,trustpilot,last_platform,last_platform_change_at,features,contact_info';
const cList = ccList.length ? ccList : [null];
const out=[];
for(const prov of providers){ for(const cc of cList){ const f = Object.assign({}, baseFilters); if(cc) f['f:cc']=cc; const pullQuery = Object.assign({}, f, { page_size: 50, sort: 'rank', fields }); out.push({ json: { _provider: prov, _country: cc||'ALL', countryCode: cc||'', _ccList: ccList, pullQuery, maxCompanies, providerCount: providers.length, countryCount: cList.length } }); } }
return out;

// Preflight: the helper's rows-less call (Insert domains to Clayroots), before the first metered
// Storeleads page. One item carrying only _meta, with keys = the row keys Process Batch (SL Batch
// Pull) writes: the helper's Check Columns refuses when the landing fields or the Storeleads
// declared extras are missing on Companies (they are register fields, never created here: scaffold
// the base with Extras = Storeleads), and creates any open key once for the run. The batches then
// call the same helper with rows and allowNew off.
const p=$('Launch Params').first().json;
const KEYS=['Domain','Company','Description','Industry Groups','Employees','Country','State','City','public_emails_clean','Plan','Revenue Est Monthly','Store Age Years','Product Count','App Spend Mo','Key Apps','Tech Stack','Trustpilot Rating','Trustpilot Reviews','Migrated From','Social Followers','Features'];
return [{ json: { _meta: { base: p.base, clientRecId: p.clientRecId, tag: p.tag||'', domainSource: 'Storeleads', allowNew: true, keys: KEYS } } }];

// Init Loop State: one static-data record carries the batch loop. Counters only; the rows never
// cross the sub-workflow boundary (the law of 2026-09-09: no execution grows with the size of the
// list, so SL Batch Pull lands its own chunk through the shared helper and answers numbers).
// kept is the spend meter (rows the child prepared for the write, what the cap counts); upserted is
// what actually landed (record ids the helper's upsert returned).
// landedDomains is the one non-counter the child sends back: the domains of this run, so the
// contacts hand-off is scoped to this pull. Strings only, and hard-capped (SCOPE_CAP) so the state
// cannot grow without bound; past the cap the hand-off falls back to the whole view and says so.
const SCOPE_CAP = 20000;
const qs = $('Build SL Query').all().map(i => ({ provider: i.json._provider, pullQuery: i.json.pullQuery }));
const cap = Math.max(1, Number($('Build SL Query').first().json.maxCompanies) || 1);
const sd = $getWorkflowStaticData('global');
sd.slBatchState = { cap, scopeCap: SCOPE_CAP, qIndex: 0, cursor: '', batchNum: 0, retried: false, remaining: cap, totals: { pulled: 0, kept: 0, upserted: 0, newDomains: 0, existingDomains: 0, withEmails: 0, failed: 0, skipped: 0, inactive: 0, duplicate: 0, dnc: 0 }, failReasons: [], providerErrors: 0, providerReason: '', stoppedWhy: '', landedDomains: [], scopeOverflow: false };
return [{ json: { action: 'continue', qIndex: 0, cursor: '', remaining: cap, queries: qs } }];

// Loop Control: reads one batch summary, adds it to the running totals, and decides the next move:
// continue (next cursor or next query), retry once after Storeleads error pages, or done.
//
// A provider that cannot be reached is a logged skip, never a crash (the Rootflows standard): error
// pages are retried once, and a second round on the same cursor stops THIS query with a reason
// instead of throwing. Same for the 500-batch guard. Build Log names every stop, and the row closes
// Failed only when nothing at all was pulled.
const res = $input.first().json || {};
const sd = $getWorkflowStaticData('global');
const st = sd.slBatchState;
if (!st) throw new Error('Loop state missing: Init Loop State did not run');
const queries = $('Init Loop State').first().json.queries || [];
const provider = () => String(((queries[st.qIndex] || {}).provider) || '?');
const nextQuery = (why) => {
  if (why) { st.stoppedWhy = (st.stoppedWhy ? st.stoppedWhy + '; ' : '') + why; }
  st.qIndex += 1; st.cursor = ''; st.retried = false;
  if (st.qIndex < queries.length && st.remaining > 0) return [{ json: { action: 'continue', qIndex: st.qIndex, cursor: '', remaining: st.remaining } }];
  return [{ json: Object.assign({ action: 'done' }, st.totals) }];
};
st.batchNum = (st.batchNum || 0) + 1;
if (st.batchNum > 500) {
  st.stoppedWhy = (st.stoppedWhy ? st.stoppedWhy + '; ' : '') + 'the batch loop hit its hard cap of 500 batches at cursor "' + st.cursor + '" (provider ' + provider() + ', query ' + (st.qIndex + 1) + '/' + queries.length + ')';
  return [{ json: Object.assign({ action: 'done' }, st.totals) }];
}
if (res.errorPages && res.errorPages > 0 && !res.pulled) {
  if (!st.retried) { st.retried = true; return [{ json: { action: 'retry', qIndex: st.qIndex, cursor: st.cursor, remaining: st.remaining } }]; }
  st.providerErrors = (st.providerErrors || 0) + Number(res.errorPages || 0);
  if (!st.providerReason) st.providerReason = String(res.errorReason || 'Storeleads returned error pages twice').slice(0, 160);
  return nextQuery('Storeleads returned error pages twice for cursor "' + st.cursor + '" (provider ' + provider() + ', query ' + (st.qIndex + 1) + '/' + queries.length + '), so that query was dropped');
}
st.retried = false;
const n = (k) => Number(res[k]) || 0;
if (res.errorPages) { st.providerErrors = (st.providerErrors || 0) + n('errorPages'); if (!st.providerReason && res.errorReason) st.providerReason = String(res.errorReason).slice(0, 160); }
for (const k of ['pulled','kept','upserted','newDomains','existingDomains','withEmails','failed','skipped','inactive','duplicate','dnc']) { st.totals[k] = (Number(st.totals[k]) || 0) + n(k); }
st.failReasons = Array.isArray(st.failReasons) ? st.failReasons : [];
for (const x of (Array.isArray(res.failReasons) ? res.failReasons : [])) { if (st.failReasons.length < 5) st.failReasons.push(String(x)); }
st.landedDomains = Array.isArray(st.landedDomains) ? st.landedDomains : [];
for (const d of (Array.isArray(res.domains) ? res.domains : [])) {
  if (st.landedDomains.length >= (st.scopeCap || 20000)) { st.scopeOverflow = true; break; }
  st.landedDomains.push(String(d));
}
st.remaining = Math.max(0, st.cap - (Number(st.totals.kept) || 0));
if (res.has_next_page && st.remaining > 0 && res.next_cursor) {
  st.cursor = String(res.next_cursor);
  return [{ json: { action: 'continue', qIndex: st.qIndex, cursor: st.cursor, remaining: st.remaining } }];
}
return nextQuery('');

// Fire Contacts: one item in Enrich Contacts' event shape (its Event Row reads launch-row keys), so
// the companies just landed get their people at once. Client, Table Companies, View Not Sourced,
// Tag, and Domains = exactly the domains this run landed, so on a base with a backlog the contacts
// pull is scoped to this pull and never re-sweeps the whole view (ruled 2026-09-09). Enrich Contacts
// writes its own launch row; nothing else is passed. Past the loop's scope cap the domain list was
// not kept in full, so Domains goes empty and the whole view is worked (Build Log says so).
const p=$('Launch Params').first().json;
const st=($getWorkflowStaticData('global').slBatchState)||{};
const domains=st.scopeOverflow?[]:Array.from(new Set((st.landedDomains||[]).map(d=>String(d||'').trim().toLowerCase()).filter(Boolean)));
return [{ json:{ Client:[p.clientRecId], Table:'Companies', View:'Not Sourced', Tag:p.tag||'', Domains:domains } }];

// Build Log: one row per run, on the launch row, status computed from the batches' failures and the
// provider verdict, skips separated from errors, Client attached (a launched run serves exactly one
// client). Records Out is what the helper's upserts returned record ids for, never the pre-write
// count. The table, the columns created and the keys dropped come from the preflight call (Check
// Base); the funnel from the loop's counters.
// A Storeleads that could not be reached (no credential, dead API, error pages twice) is a logged
// skip, never a crash: the row closes Failed only when nothing at all could be pulled.
const p=$('Launch Params').first().json;
let cfg={}; try{ cfg=$('Check Base').first().json||{}; }catch(e){}
const sd=$getWorkflowStaticData('global');
const st=(sd.slBatchState)||{};
const t=Object.assign({ pulled:0, kept:0, upserted:0, newDomains:0, existingDomains:0, withEmails:0, failed:0, skipped:0, inactive:0, duplicate:0, dnc:0 }, st.totals||{});
const failed=[];
for(const r of (st.failReasons||[])) failed.push({ name:'upsert', reason:String(r).slice(0,140) });
const errors=Number(t.failed)||0;
if(errors>failed.length) failed.push({ name:'upsert', reason:(errors-failed.length)+' more rows returned no record id' });
const providerErrors=Number(st.providerErrors)||0;
const providerDown=!t.pulled&&providerErrors>0;
if(providerDown) failed.push({ name:'Storeleads', reason:'Storeleads could not be pulled: '+(st.providerReason||'error pages only') });
let fired=false, scope=0; try{ const fc=$('Fire Contacts').first().json||{}; fired=true; scope=(fc.Domains||[]).length; }catch(e){}
let queries=[]; try{ queries=$('Build SL Query').all().map(i=>i.json||{}); }catch(e){}
const providers=Array.from(new Set(queries.map(q=>q._provider).filter(Boolean)));
const countries=Array.from(new Set(queries.map(q=>q._country).filter(Boolean)));
const SKIP=new Set(['page_size','sort','fields','f:cc']);
const filters=Object.entries((queries[0]||{}).pullQuery||{}).filter(([k])=>!SKIP.has(k)).map(([k,v])=>k+'='+v).join(', ');
let dur=0; try{ dur=Math.max(0,Math.round(($now.toMillis()-new Date(p.startedAt).getTime())/1000)); }catch(e){}
const fmt=v=>Number(v||0).toLocaleString('en-US');
const tableName=cfg.tableName||'Companies';
const lines=[
  '**'+fmt(t.pulled)+' stores pulled, '+fmt(t.upserted)+' landed on '+tableName+' ('+fmt(t.newDomains)+' new, '+fmt(t.existingDomains)+' already held and refreshed)**',
  '',
  '**Source:** Storeleads, providers '+(providers.join(', ')||'all')+', countries '+(countries.join(', ')||'ALL')+', cap '+fmt(st.cap||p.maxCompanies),
  '**Filters:** '+(filters||'none'),
  '**Tag:** '+(p.tag||'none'),
  '**Rule:** every active store the search answers is landed on Domain; a held company is refreshed with the new pull (Domain Source kept, Tag re-stamped); DNC domains dropped',
  '',
  '**Funnel**',
  '- **Pulled:** '+fmt(t.pulled),
  '- **Kept (active, unique domain, under the cap):** '+fmt(t.kept),
  '- **Landed (record id returned):** '+fmt(t.upserted)+' ('+fmt(t.newDomains)+' new, '+fmt(t.existingDomains)+' already held)',
  '- **With public emails:** '+fmt(t.withEmails),
  '- **Without public emails:** '+fmt(Math.max(0,t.upserted-t.withEmails)),
  '- **Batches:** '+fmt(st.batchNum)
];
if(Array.isArray(cfg.createdColumns)&&cfg.createdColumns.length) lines.push('- **Columns created (open fields):** '+cfg.createdColumns.join(', '));
if(Array.isArray(cfg.droppedKeys)&&cfg.droppedKeys.length) lines.push('- **Keys dropped:** '+cfg.droppedKeys.map(d=>d.key+' ('+d.why+')').join(', '));
lines.push('', '**Contacts:** '+(fired?('Enrich Contacts fired once on Companies view "Not Sourced"'+(scope?(', scoped to the '+fmt(scope)+' domains of this pull'):(st.scopeOverflow?', unscoped: this pull is past the '+fmt(st.scopeCap)+'-domain scope cap, so the whole view is worked':', unscoped'))+'; it writes its own launch row'):'not fired, nothing landed'));
const skips=[];
if(t.skipped) skips.push(fmt(t.skipped)+' empty domain');
if(t.inactive) skips.push(fmt(t.inactive)+' inactive store');
if(t.duplicate) skips.push(fmt(t.duplicate)+' duplicate domain in the pull');
if(t.dnc) skips.push(fmt(t.dnc)+' on the DNC table');
if(providerErrors&&t.pulled) skips.push(fmt(providerErrors)+' Storeleads page(s) failed ('+(st.providerReason||'no reason given')+')');
if(skips.length) lines.push('', '**Skipped ('+skips.join(', ')+')**');
if(st.stoppedWhy) lines.push('', '**Stopped early:** '+st.stoppedWhy);
if(failed.length){ lines.push('', '**Failures ('+failed.length+')**'); for(const f of failed.slice(0,10)) lines.push('- '+f.name+': '+f.reason); }
const log={
  'Automation':'Discover Storeleads Companies',
  'Status': providerDown?'Failed':(failed.length?'Succeeded with errors':'Succeeded'),
  'Trigger':'form',
  'Errors': failed.length,
  'Run at': $now.toISO(),
  'Target': tableName+' ('+(cfg.tableId||'')+')',
  'Records In': t.pulled,
  'Records Out': t.upserted,
  'Duration s': dur,
  'Description': lines.join('\n'),
  'Execution Link':'https://n8n.flowroots.com/workflow/'+$workflow.id+'/executions/'+$execution.id,
  'Execution ID': String($execution.id),
  'Client': [p.clientRecId]
};
return [{ json: log }];
